item.command:
/bin/zsh -lc "python3 -c 'import json; from pathlib import Path; wanted={\"프로토콜\",\"확인하다\",\"검사하다\",\"검토하다\",\"알리다\",\"통과하다\",\"시작하다\",\"수정하다\",\"착용하다\",\"발송하다\",\"닫다\",\"열다\",\"교체하다\"};
def walk(x):
 if isinstance(x,dict):
  if x.get(\"lemma\") in wanted: print(json.dumps(x,ensure_ascii=False))
  else:
   for v in x.values(): walk(v)
 elif isinstance(x,list):
  for v in x: walk(v)
for p in (Path(\"lexicon/core.json\"),Path(\"lexicon/domains/software.json\")):
 if p.is_file(): walk(json.loads(p.read_text()))'"

